432	/// How many device frames may wait for the frame thread.
433	const FRAMES: usize = 64;
434	
435	/// The most a request line and its headers may take, and the most a
436	/// body may be.
437	pub const MAX_HEAD: usize = 8 * 1024;
438	pub const MAX_BODY: usize = 64 * 1024;
439	
440	/// The head of one HTTP/1.1 request: method, target, lowercased
441	/// headers, body. `None` at a clean end of stream before any byte; an
442	/// oversized or malformed request is an error that closes the
443	/// connection.
444	fn read_request<R: Read>(reader: &mut BufReader<R>) -> io::Result<Option<RemoteRequest>> {
445	    let mut line = String::new();
446	    if reader.read_line(&mut line)? == 0 {
447	        return Ok(None);
448	    }
449	    let mut parts = line.split_whitespace();
450	    let (Some(method), Some(target)) = (parts.next(), parts.next()) else {
451	        return Err(io::Error::new(
452	            io::ErrorKind::InvalidData,
453	            "bad request line",
454	        ));
455	    };
456	    let mut headers: Vec<(String, String)> = Vec::new();
457	    let mut total = line.len();
458	    loop {
459	        let mut h = String::new();
460	        if reader.read_line(&mut h)? == 0 {
461	            return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "headers cut"));
462	        }
463	        total += h.len();
464	        if total > MAX_HEAD {
465	            return Err(io::Error::new(io::ErrorKind::InvalidData, "head too large"));
466	        }
467	        let h = h.trim_end();
468	        if h.is_empty() {
469	            break;
470	        }
471	        if let Some((n, v)) = h.split_once(':') {
472	            headers.push((n.trim().to_ascii_lowercase(), v.trim().to_owned()));
473	        }
474	    }
475	    let header = |name: &str| {
476	        headers
477	            .iter()
478	            .find(|(n, _)| n == name)
479	            .map(|(_, v)| v.as_str())
480	    };
481	    let length: usize = header("content-length")
482	        .and_then(|v| v.parse().ok())
483	        .unwrap_or(0);
484	    if length > MAX_BODY {
485	        return Err(io::Error::new(io::ErrorKind::InvalidData, "body too large"));
486	    }
487	    let bearer = header("authorization")
488	        .and_then(|v| v.strip_prefix("Bearer "))
489	        .map(|t| t.trim().to_owned())
490	        .filter(|t| !t.is_empty());
491	    let upgrade = header("upgrade")
492	        .filter(|u| u.eq_ignore_ascii_case("websocket"))
493	        .and_then(|_| header("sec-websocket-key"))
494	        .map(str::to_owned);
495	    let (path, query) = target.split_once('?').unwrap_or((target, ""));
496	    let query = query
497	        .split('&')
498	        .filter(|s| !s.is_empty())
499	        .map(|pair| {
500	            let (n, v) = pair.split_once('=').unwrap_or((pair, ""));
501	            (n.to_owned(), v.to_owned())
502	        })
503	        .collect();
504	    let mut body = vec![0; length];
505	    reader.read_exact(&mut body)?;
506	    Ok(Some(RemoteRequest {
507	        method: method.to_owned(),
508	        path: path.to_owned(),
509	        query,
510	        body,
511	        bearer,
512	        upgrade,
513	    }))
514	}
