516	/// The 101 that switches a connection to WebSocket. The request was
517	/// already read by `read_request`, so `tungstenite::accept` cannot be
518	/// used; the stream is wrapped with `from_raw_socket` after this.
519	fn respond_upgrade<W: Write>(w: &mut W, key: &str) -> io::Result<()> {
